# Flood fill from all edge 4s
def flood_fill_4s(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    stack = []

    # Add all edge 4s
    for r in range(h):
        if grid[r][0] == 4:
            stack.append((r,0))
        if grid[r][w-1] == 4:
            stack.append((r,w-1))
    for c in range(w):
        if grid[0][c] == 4:
            stack.append((0,c))
        if grid[h-1][c] == 4:
            stack.append((h-1,c))

    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == 4 and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    stack.append((nr,nc))
    return visited

